<?php $total=array_sum(array_column($plans,'total')); $paid=array_sum(array_column($plans,'paid')); ?><div class="stats-grid three"><article class="stat"><span>Presupuestos vigentes</span><strong><?= money($total) ?></strong><small>Procedimientos sin cancelar</small></article><article class="stat"><span>Cobros registrados</span><strong><?= money($paid) ?></strong><small>Pagos sin anular</small></article><article class="stat"><span>Saldo pendiente</span><strong><?= money($total-$paid) ?></strong><small>Sobre los planes registrados</small></article></div>
<section class="panel form-panel"><h2>Registrar un cobro</h2><form method="post" class="form-grid" data-loading><?= csrf_field() ?><input type="hidden" name="request_key" value="<?= e($_POST['request_key'] ?? bin2hex(random_bytes(24))) ?>"><?php choose('plan_id','Plan / saldo',array_combine(array_column($plans,'id'),array_map(fn($p)=>'#'.$p['id'].' · '.$p['patient'].' · Saldo '.money((float)$p['total']-(float)$p['paid']),$plans)) ?: [],$_POST['plan_id'] ?? ''); field('amount','Importe',$_POST['amount'] ?? '','number',true,'min="0.01" step="0.01"'); choose('method','Método de pago',['cash'=>'Efectivo','transfer'=>'Transferencia','card'=>'Tarjeta'],$_POST['method'] ?? 'cash'); field('reference','Referencia (opcional)',$_POST['reference'] ?? '','text',false); ?><div class="full"><button class="button">Registrar pago</button><small class="muted"> Se permiten pagos parciales hasta cubrir el saldo del plan.</small></div></form></section>
<section class="panel"><div class="panel-heading"><h2>Historial de cobros</h2><span class="muted">Comprobantes internos · sin validez tributaria</span></div><div class="table-wrap" tabindex="0" role="region" aria-label="Tabla de registros"><table><thead><tr><th>Comprobante</th><th>Paciente</th><th>Importe</th><th>Método</th><th>Fecha</th><th>Estado / acción</th></tr></thead><tbody><?php foreach($payments as $p): ?><tr><td><a class="table-link" href="<?= e(url('/admin/receipt?id='.$p['id'])) ?>"><?= e($p['number']) ?></a></td><td><?= e($p['patient']) ?></td><td><strong><?= money($p['amount']) ?></strong></td><td><?= e(label($p['method'])) ?></td><td><?= local_date($p['created_at']) ?></td><td><?php if($p['voided_at']): ?><span class="badge cancelled">Anulado</span><small><?= e($p['void_reason']) ?></small><?php else: ?><details><summary>Anular pago</summary><form method="post" class="stack" data-confirm="Se anulará el pago y se restituirá el saldo pendiente. El registro se conservará."><?= csrf_field() ?><input type="hidden" name="action" value="void"><input type="hidden" name="id" value="<?= (int)$p['id'] ?>"><?php field('void_reason','Motivo de anulación'); ?><button class="button danger small">Anular</button></form></details><?php endif; ?></td></tr><?php endforeach; ?><?php if(!$payments): ?><tr><td colspan="6" class="empty">Todavía no hay pagos. Crea un plan para registrar el primer cobro.</td></tr><?php endif; ?></tbody></table></div></section>
<section class="panel"><div class="panel-heading"><h2>Saldos por plan</h2></div><div class="table-wrap" tabindex="0" role="region" aria-label="Tabla de registros"><table><thead><tr><th>Plan</th><th>Paciente</th><th>Presupuesto</th><th>Pagado</th><th>Saldo</th></tr></thead><tbody><?php foreach($plans as $p): ?><tr><td>#<?= (int)$p['id'] ?> · <?= e($p['name']) ?></td><td><?= e($p['patient']) ?></td><td><?= money($p['total']) ?></td><td><?= money($p['paid']) ?></td><td><?= money((float)$p['total']-(float)$p['paid']) ?></td></tr><?php endforeach; ?></tbody></table></div></section>
